final storage = FirebaseStorage.instance;

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  await Firebase.initializeApp();
  runApp(const KanchanpurApp());
}

class KanchanpurApp extends StatelessWidget {
  const KanchanpurApp({super.key});
  @override Widget build(BuildContext context) => MaterialApp(
    debugShowCheckedModeBanner:false,
    title:'কাঞ্চনপুর স্পোর্টিং ক্লাব',
    theme:ThemeData(useMaterial3:true,colorSchemeSeed:Colors.green,scaffoldBackgroundColor:const Color(0xFFF5F8F6)),
    home:const AppController(),
  );
}

class AppController extends StatefulWidget { const AppController({super.key}); @override State<AppController> createState()=>_AppControllerState(); }
class _AppControllerState extends State<AppController> {
  bool loading=true; User? user; Map<String,dynamic>? profile;
  @override void initState(){super.initState(); _load(); auth.authStateChanges().listen((_)=>_load());}
  Future<void> _load() async {
    final u=auth.currentUser;
    if(u==null){if(mounted)setState(()=>{user=null,profile=null,loading=false});return;}
    try{
      final s=await db.collection('profiles').doc(u.uid).get();
      if(!s.exists){await auth.signOut();if(mounted)setState(()=>{user=null,profile=null,loading=false});return;}
      if(mounted)setState(()=>{user=u,profile=s.data(),loading=false});
    }catch(_){await auth.signOut();if(mounted)setState(()=>{user=null,profile=null,loading=false});}
  }
  @override Widget build(BuildContext c){
    if(loading)return const Scaffold(body:Center(child:CircularProgressIndicator()));
    if(user==null)return const AuthPage();
    if(profile?['role']=='admin')return AdminHomePage(username:profile?['name']?.toString()??'Admin',onLogout:auth.signOut);
    return HomePage(username:profile?['name']?.toString()??'Member',phone:profile?['phone']?.toString()??'',onLogout:auth.signOut);
  }
}

class AuthPage extends StatefulWidget { const AuthPage({super.key}); @override State<AuthPage> createState()=>_AuthPageState(); }
class _AuthPageState extends State<AuthPage>{
  bool signup=false,busy=false,hide=true; final name=TextEditingController(),phone=TextEditingController(),pass=TextEditingController();
  @override void dispose(){name.dispose();phone.dispose();pass.dispose();super.dispose();}
  String normalize(String x){var p=x.trim().replaceAll(RegExp(r'[\s-]'), '');if(p.startsWith('+88'))p=p.substring(3);if(p.startsWith('88')&&p.length==13)p=p.substring(2);return p;}
  String email(String p)=>'${normalize(p)}@phone-login.local';
  void msg(String s)=>ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(s)));
  Future<void> submit() async{
    final n=name.text.trim(),p=normalize(phone.text),pw=pass.text;
    if(n.isEmpty||p.isEmpty||pw.isEmpty){msg('সব তথ্য পূরণ করুন।');return;}
    if(!RegExp(r'^01[3-9]\d{8}$').hasMatch(p)){msg('সঠিক ১১ সংখ্যার বাংলাদেশি মোবাইল নাম্বার দিন।');return;}
    if(pw.length<6){msg('Password কমপক্ষে ৬ অক্ষরের হতে হবে।');return;}
    setState(()=>busy=true);
    try{
      if(signup){
        final r=await auth.createUserWithEmailAndPassword(email:email(p),password:pw); final u=r.user!;
        await db.collection('profiles').doc(u.uid).set({'id':u.uid,'name':n,'phone':p,'role':'member','email':email(p),'created_at':FieldValue.serverTimestamp()});
        msg('Account তৈরি হয়েছে।');
      }else{
        await auth.signOut(); final r=await auth.signInWithEmailAndPassword(email:email(p),password:pw); final u=r.user!;
        final s=await db.collection('profiles').doc(u.uid).get(); if(!s.exists){await auth.signOut();throw Exception('এই Mobile Number-এর কোনো নিবন্ধিত account নেই।');}
        final d=s.data()!; if((d['name']?.toString().trim().toLowerCase()??'')!=n.toLowerCase()||normalize(d['phone']?.toString()??'')!=p){await auth.signOut();throw Exception('Username, Mobile Number অথবা Password ভুল।');}
        msg('Login সফল হয়েছে।');
      }
    }on FirebaseAuthException catch(e){msg(e.message??'Firebase Authentication error');}on FirebaseException catch(e){msg(e.message??'Firebase error');}catch(e){msg(e.toString().replaceFirst('Exception: ',''));}finally{if(mounted)setState(()=>busy=false);}
  }
  @override Widget build(BuildContext c)=>Scaffold(body:SafeArea(child:Center(child:SingleChildScrollView(padding:const EdgeInsets.all(24),child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:520),child:Column(children:[_Logo(size:105),SizedBox(height:14),Text('কাঞ্চনপুর স্পোর্টিং ক্লাব',textAlign:TextAlign.center,style:TextStyle(fontSize:27,fontWeight:FontWeight.bold)),SizedBox(height:5),Text('এটি একটি ক্রীড়া ও সেচ্ছাসেবী সংগঠন'),SizedBox(height:30),Card(child:Padding(padding:const EdgeInsets.all(20),child:Column(children:[Text(signup?'নতুন একাউন্ট খুলুন':'Login করুন',style:const TextStyle(fontSize:22,fontWeight:FontWeight.bold)),const SizedBox(height:20),TextField(controller:name,decoration:const InputDecoration(labelText:'Username',prefixIcon:Icon(Icons.person_outline))),const SizedBox(height:12),TextField(controller:phone,keyboardType:TextInputType.phone,decoration:const InputDecoration(labelText:'Mobile Number',hintText:'01XXXXXXXXX',prefixIcon:Icon(Icons.phone_outlined))),const SizedBox(height:12),TextField(controller:pass,obscureText:hide,decoration:InputDecoration(labelText:'Password',prefixIcon:const Icon(Icons.lock_outline),suffixIcon:IconButton(onPressed:()=>setState(()=>hide=!hide),icon:Icon(hide?Icons.visibility:Icons.visibility_off)))),const SizedBox(height:18),SizedBox(width:double.infinity,height:52,child:FilledButton(onPressed:busy?null:submit,child:busy?const CircularProgressIndicator():Text(signup?'Signup':'Login'))),TextButton(onPressed:busy?null:()=>setState(()=>signup=!signup),child:Text(signup?'আগে account থাকলে Login করুন':'নতুন account খুলুন'))])))])))));
