Widget _dashboard()=>ListView(padding:const EdgeInsets.all(18),children:[Text('স্বাগতম ${widget.username}',style:const TextStyle(fontSize:25,fontWeight:FontWeight.bold)),const SizedBox(height:18),_AdminStat('Applications', 'Firestore থেকে দেখা হবে', Icons.people),const SizedBox(height:10),_AdminStat('Payments','Firestore থেকে দেখা হবে',Icons.payments)]);
Widget _apps()=>StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:db.collection('member_applications').orderBy('created_at',descending:true).snapshots(),builder:(c,s){if(s.hasError)return Center(child:Text('Applications error: ${s.error}'));if(!s.hasData)return const Center(child:CircularProgressIndicator());final docs=s.data!.docs;if(docs.isEmpty)return const Center(child:Text('কোনো আবেদন নেই।'));return ListView.builder(padding:const EdgeInsets.all(12),itemCount:docs.length,itemBuilder:(_,i){final a=docs[i].data();return Card(child:ExpansionTile(title:Text(a['name']?.toString()??''),subtitle:Text('${a['mobile']??''} • ${a['status']??''}'),children:[Padding(padding:const EdgeInsets.all(15),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[for(final k in ['username','father_name','mother_name','birth_year','nid','division','district','thana','post_code','village','blood_group','mobile'])Text('$k: ${a[k]??''}'),if('${a['image_url']??''}'.isNotEmpty)Padding(padding:const EdgeInsets.symmetric(vertical:10),child:Image.network(a['image_url'],height:150,errorBuilder:(_,__,___)=>const Text('ছবি দেখা যায়নি'))),Row(children:[Expanded(child:OutlinedButton(onPressed:()=>update('member_applications',docs[i].id,'Rejected'),child:const Text('Reject'))),const SizedBox(width:10),Expanded(child:FilledButton(onPressed:()=>update('member_applications',docs[i].id,'Approved'),child:const Text('Approve')))])]))]));});});
Widget _payments()=>StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:db.collection('payments').orderBy('created_at',descending:true).snapshots(),builder:(c,s){if(s.hasError)return Center(child:Text('Payments error: ${s.error}'));if(!s.hasData)return const Center(child:CircularProgressIndicator());final docs=s.data!.docs;if(docs.isEmpty)return const Center(child:Text('কোনো payment নেই।'));return ListView.builder(padding:const EdgeInsets.all(12),itemCount:docs.length,itemBuilder:(_,i){final p=docs[i].data();return Card(child:ListTile(title:Text('${p['type']=='chanda'?'চাঁদা':'Donation'} • ${p['amount']} টাকা'),subtitle:Text('${p['username']??''}\n${p['method']??''} • ${p['month']??''}\nAccount: ${p['account']??''}\nTXID: ${p['transaction_id']??''}\nStatus: ${p['status']??''}'),isThreeLine:true,trailing:PopupMenuButton<String>(onSelected:(v)=>update('payments',docs[i].id,v),itemBuilder:(_)=>const[PopupMenuItem(value:'Approved',child:Text('Approve')),PopupMenuItem(value:'Rejected',child:Text('Reject'))])));});});
}

class _AdminStat extends StatelessWidget{final String title,value;final IconData icon;const _AdminStat(this.title,this.value,this.icon);@override Widget build(BuildContext c)=>Card(child:ListTile(leading:Icon(icon,size:32),title:Text(title),subtitle:Text(value)));}
class ProfilePage extends StatelessWidget{final String username,phone;const ProfilePage({super.key,required this.username,required this.phone});@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('প্রোফাইল')),body:Padding(padding:const EdgeInsets.all(18),child:Card(child:ListTile(leading:const CircleAvatar(child:Icon(Icons.person)),title:Text(username),subtitle:Text(phone)))));}
class InfoPage extends StatelessWidget{final String title,text;const InfoPage({super.key,required this.title,required this.text});@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:Text(title)),body:Padding(padding:const EdgeInsets.all(20),child:Text(text,style:const TextStyle(fontSize:17,height:1.7))));}
class GalleryPage extends StatelessWidget{const GalleryPage({super.key});@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('গ্যালারী')),body:const Center(child:Text('গ্যালারীর ছবি Admin Panel থেকে যুক্ত করার ব্যবস্থা পরের ধাপে করা হবে.',textAlign:TextAlign.center)));}
class AboutPage extends StatelessWidget{const AboutPage({super.key});@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('About')),body:const Center(child:Padding(padding:EdgeInsets.all(25),child:Text('এই Apps টি কাঞ্চনপুর মানুষের জন্য বানানো হয়েছে.\n\nApps. SEO- শাহাদাত হোসেন রাজু\nপ্রধান সম্পাদক, কাঞ্চনপুর স্পোর্টিং ক্লাব',textAlign:TextAlign.center,style:TextStyle(fontSize:18,height:1.8))));}
class _RunningMessage extends StatefulWidget{const _RunningMessage();@override State<_RunningMessage>createState()=>_RunningMessageState();}
class _RunningMessageState extends State<_RunningMessage>with SingleTickerProviderStateMixin{late AnimationController c;@override void initState(){super.initState();c=AnimationController(vsync:this,duration:const Duration(seconds:9))..repeat();}@override void dispose(){c.dispose();super.dispose();}@override Widget build(BuildContext x)=>Container(height:46,clipBehavior:Clip.hardEdge,decoration:BoxDecoration(color:Colors.green.withOpacity(.1),borderRadius:BorderRadius.circular(12)),child:AnimatedBuilder(animation:c,builder:(_,child)=>Align(alignment:Alignment(1.8-c.value*3.6,0),child:child),child:const Text('আসুন সবাই মিলে গড়ি সুন্দর ও নিরপেক্ষ সমাজ / মাদক কে না বলুন।',maxLines:1,softWrap:false,style:TextStyle(fontWeight:FontWeight.w700))));}
class _StatusCard extends StatelessWidget{final String title,value;final IconData icon;const _StatusCard({required this.title,required this.value,required this.icon});@override Widget build(BuildContext c)=>Card(child:ListTile(leading:CircleAvatar(child:Icon(icon)),title:Text(title),subtitle:Text(value)));}
class _Logo extends StatelessWidget{final double size;const _Logo({required this.size});@override Widget build(BuildContext c)=>Image.asset('assets/club_logo.png',width:size,height:size,fit:BoxFit.contain,errorBuilder:(_,__,___)=>Container(width:size,height:size,decoration:BoxDecoration(shape:BoxShape.circle,color:Colors.green.shade50,border:Border.all(color:Colors.green,width:2)),child:const Icon(Icons.sports_soccer,size:48,color:Colors.green)));}
